#include <stdio.h>

int main() {
    int numbers[] = {12, 45, 3, 89, 27, 56};
    int n = sizeof(numbers) / sizeof(numbers[0]);
    int smallest = numbers[0];

    for (int i = 1; i < n; i++) {
        if (numbers[i] < smallest) {
            smallest = numbers[i];
        }
    }

    printf("Smallest number: %d\n", smallest);
    return 0;
}
